func GetProduct(ctx context.Context, id string) (*Product, error) {
    key := "product:" + id
    cached, err := rdb.Get(ctx, key).Bytes()
    if err != nil {
        // Any error -- miss OR outage -- falls through to the DB.
        p, derr := db.QueryProduct(ctx, id)
        if derr != nil {
            return nil, derr
        }
        rdb.Set(ctx, key, marshal(p), 0)
        return p, nil
    }
    var p Product
    json.Unmarshal(cached, &p)
    return &p, nil
}
